using UnityEngine;
using UnityEngine.InputSystem;
using UnityEngine.UIElements;
using UnityEngine.XR.Interaction.Toolkit.Interactors;
using UnityEngine.XR.Interaction.Toolkit.Interactors.Casters;

/// <summary>
/// Generated by Claude with simple prompting to get the scrolling to work.
/// Scrolls the top-most ScrollView in a world-space UIDocument that the
/// right controller is pointing at.
///
/// SETUP:
///   1. Add this component to any persistent GameObject (e.g. XR Origin).
///   2. Assign rightInteractor (the NearFarInteractor on the right controller).
///   3. Assign rightScrollAction (Vector2, bind to <XRController>{RightHand}/thumbstick).
///
/// REQUIREMENTS:
///   - com.unity.inputsystem
///   - com.unity.xr.interaction.toolkit 3.x
///   - com.unity.ui (UI Toolkit)
/// </summary>
public class PlayerUIScrollHandler : MonoBehaviour
{
    [Header("Controller")]
    public NearFarInteractor rightInteractor;

    [Header("Input")]
    [Tooltip("Vector2 action — bind to <XRController>{RightHand}/thumbstick")]
    public InputActionReference rightScrollAction;

    [Header("Settings")]
    [Tooltip("Pixels per second when joystick is fully deflected.")]
    public float scrollSpeed = 600f;

    [Tooltip("Joystick input below this magnitude is ignored.")]
    [Range(0f, 0.5f)]
    public float threshold = 0.1f;

    [Tooltip("Flip if push-up scrolls the wrong way.")]
    public bool invertVertical = false;

    // -------------------------------------------------------------------------

    private void OnEnable()  => rightScrollAction?.action?.Enable();
    private void OnDisable() => rightScrollAction?.action?.Disable();

    private void Update()
    {
        if (rightInteractor == null || rightScrollAction?.action == null)
            return;

        // 1. Check scroll input is significant
        Vector2 raw = rightScrollAction.action.ReadValue<Vector2>();
        if (Mathf.Abs(raw.y) < threshold)
            return;

        float scrollY = invertVertical ? raw.y : -raw.y;

        if (rightInteractor.farInteractionCaster is not ICurveInteractionCaster farCaster)
            return;

        Vector3 origin    = farCaster.castOrigin.position;
        Vector3 direction = (farCaster.lastSamplePoint - origin).normalized;

        if (!Physics.Raycast(origin, direction, out RaycastHit hit, Mathf.Infinity))
            return;

        GameObject target = hit.collider.gameObject;
        if (target == null)
            return;

        // 3. Check it has a UIDocument
        UIDocument doc = target.GetComponentInParent<UIDocument>();
        if (doc == null)
            return;

        // 4. Find and scroll the top-most ScrollView in the document
        ScrollView scrollView = FindFirstScrollView(doc.rootVisualElement);
        if (scrollView == null)
            return;

        float delta = scrollY * scrollSpeed * Time.deltaTime;
        scrollView.verticalScroller.value = Mathf.Clamp(
            scrollView.verticalScroller.value + delta,
            scrollView.verticalScroller.lowValue,
            scrollView.verticalScroller.highValue
        );
    }

    /// <summary>
    /// Depth-first search for the first ScrollView in the visual tree.
    /// </summary>
    private static ScrollView FindFirstScrollView(VisualElement root)
    {
        if (root == null)
            return null;

        if (root is ScrollView sv)
            return sv;

        foreach (VisualElement child in root.Children())
        {
            ScrollView found = FindFirstScrollView(child);
            if (found != null)
                return found;
        }

        return null;
    }
}